   {
        let remoteArr= searchQuery.locationType.split('|');

        for(let iter in remoteArr){
            if(remoteArr[iter]==="LAT_LNG"){
                remoteArr[iter]="No";
            }
            else if(remoteArr[iter]==="ANY"){
                remoteArr[iter]="Yes";
            }
            else{
                remoteArr[iter]="";
            }
        }
        remoteEligible= remoteArr.toString();
   }

   if(searchQuery && searchQuery.tags5)
